`timescale 1ns/1ps

// Self-checking testbench for npu_fp16_add.
// Vectors (src/test/vectors/hx_fp16_add.txt, generated by
// generate_hx_numeric_vectors.py from the hx_numeric golden model): directed
// corner cross products for both add and sub (signed zeros, subnormals,
// min/max normal, Inf, Inf - Inf, NaN payloads, overflow, cancellation),
// halfway rounding cases around 1.0, plus 20000 random cases (raw bit
// patterns, and values with nearby exponents incl. near-total cancellation).
// The driver issues back-to-back operations with random idle gaps; every
// cycle out_valid must equal in_valid delayed by exactly LAT clocks and each
// result must match in issue order. A reset with operations in flight must
// drop them.
module tb_npu_fp16_add;
    localparam integer LAT = 3;
    localparam integer MAXV = 32768;

    logic clk = 1'b0;
    logic rst_n;
    logic in_valid = 1'b0;
    logic [15:0] a = '0, b = '0;
    logic sub = 1'b0;
    logic out_valid;
    logic [15:0] y;

    npu_fp16_add dut (
        .clk(clk), .rst_n(rst_n), .in_valid(in_valid), .a(a), .b(b), .sub(sub),
        .out_valid(out_valid), .y(y)
    );
    always #5 clk = ~clk;

    logic [15:0] va [0:MAXV-1];
    logic [15:0] vb [0:MAXV-1];
    logic [15:0] vy [0:MAXV-1];
    logic vs [0:MAXV-1];
    integer count, file, status, issued, checked, seed, i, gaps;
    logic [LAT-1:0] valid_history;
    reg [8*256-1:0] header;

    task automatic mismatch(input [8*80-1:0] what);
        begin
            $display("MISMATCH tb_npu_fp16_add: %0s (vector %0d a=%h b=%h sub=%0d y=%h expected %h)",
                     what, checked, va[checked], vb[checked], vs[checked], y,
                     vy[checked]);
            $fatal(1);
        end
    endtask

    // One clock: drive the inputs, then check the outputs of the next cycle.
    task automatic cycle(input logic valid, input integer index);
        begin
            @(negedge clk);
            in_valid = valid;
            a = valid ? va[index] : 16'hx;
            b = valid ? vb[index] : 16'hx;
            sub = valid ? vs[index] : 1'bx;
            @(posedge clk);
            #1;
            valid_history = {valid_history[LAT-2:0], valid};
            if (out_valid !== valid_history[LAT-1]) mismatch("out_valid latency");
            if (out_valid) begin
                if (y !== vy[checked]) mismatch("result");
                checked = checked + 1;
            end
        end
    endtask

    initial begin
        file = $fopen("vectors/hx_fp16_add.txt", "r");
        if (file == 0) file = $fopen("src/test/vectors/hx_fp16_add.txt", "r");
        if (file == 0) begin
            $display("MISMATCH tb_npu_fp16_add: cannot open hx_fp16_add.txt");
            $fatal(1);
        end
        status = $fgets(header, file);
        status = $fscanf(file, "%d\n", count);
        if (count > MAXV || count < 20000) begin
            $display("MISMATCH tb_npu_fp16_add: bad vector count %0d", count);
            $fatal(1);
        end
        for (i = 0; i < count; i = i + 1) begin
            status = $fscanf(file, "%h %h %d %h\n", va[i], vb[i], vs[i], vy[i]);
            if (status != 4) begin
                $display("MISMATCH tb_npu_fp16_add: short vector file at %0d", i);
                $fatal(1);
            end
        end
        $fclose(file);

        rst_n = 1'b0;  // X -> 0 at time 0 triggers the asynchronous reset
        seed = 32'h136_0002;
        valid_history = '0;
        issued = 0;
        checked = 0;
        gaps = 0;
        #1;
        if (out_valid !== 1'b0) mismatch("reset clears out_valid");
        repeat (2) @(negedge clk);
        rst_n = 1'b1;

        // Reset with operations in flight: they must never come out.
        @(negedge clk);
        in_valid = 1'b1;
        a = 16'h3c00;
        b = 16'h3c00;
        @(posedge clk);
        #1;
        @(negedge clk);
        in_valid = 1'b0;
        rst_n = 1'b0;
        #1;
        if (out_valid !== 1'b0) mismatch("mid-flight reset clears out_valid");
        @(negedge clk);
        rst_n = 1'b1;
        repeat (LAT + 1) begin
            @(posedge clk);
            #1;
            if (out_valid !== 1'b0) mismatch("flushed operation reappeared");
        end

        while (issued < count) begin
            // Mostly back-to-back, with random bursts of idle cycles.
            if (($random(seed) & 7) == 0) begin
                cycle(1'b0, 0);
                gaps = gaps + 1;
            end else begin
                cycle(1'b1, issued);
                issued = issued + 1;
            end
        end
        repeat (LAT + 2) cycle(1'b0, 0);
        if (checked != count) begin
            $display("MISMATCH tb_npu_fp16_add: %0d of %0d results", checked, count);
            $fatal(1);
        end
        $display("PASS tb_npu_fp16_add vectors=%0d idle_cycles=%0d latency=%0d",
                 count, gaps, LAT);
        $finish;
    end
endmodule
